pi: float = 3.14159265
print(f"[{pi:.2f}] [{pi:8.3f}] [{pi:<8.1f}] [{pi:^9.2f}] [{pi:08.2f}] [{-pi:08.2f}]")
print(f"[{pi:.0f}] [{2.5:.0f}] [{0.5:.0f}] [{1.5:.0f}] [{3.5:.0f}]")
print(f"[{1234567.891:,.2f}] [{pi:+.1f}] [{-0.0:.1f}] [{-0.001:.2f}]")
print(f"[{pi:f}] [{1e22:.1f}] [{0.1 + 0.2:.20f}]")
print(f"[{1.5:10}] [{1.5:<10}] [{1.0:5}] [{1e16:>10}]")
inf: float = float("inf")
nan: float = float("nan")
print(f"[{inf:6.1f}] [{nan:.1f}] [{-inf:8}] [{inf:08.1f}]")
